def is_multiply_prime(a):
    """Returns True if the given number is the multiplication of 3 prime numbers, False otherwise."""
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    for i in range(2, 100):
        if a % i != 0:
            continue
        if is_prime(i):
            b = a // i
            for j in range(i, 100):
                if b % j != 0:
                    continue
                if is_prime(j):
